@tailwind base;
@tailwind components;
@tailwind utilities;

:root {
  --warm-bg: #FFFFFF;
  --warm-bg-2: #EFE7D8;
  --warm-bg-3: #F5EFE3;
  --ink: #0E1B2E;
  --ink-2: #475569;
  --dark: #0E1B2E;
  --accent: #A87E34;
}

html, body {
  background-color: var(--warm-bg);
  color: var(--ink);
  font-family: 'Inter', system-ui, -apple-system, sans-serif;
  font-size: 16px;
  font-weight: 400;
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

.font-serif-display {
  font-family: 'Cormorant Garamond', 'Georgia', serif;
  font-optical-sizing: auto;
  font-weight: 500;
  letter-spacing: -0.012em;
}

.font-serif-display.font-light {
  font-weight: 500;
}

.font-editorial {
  font-family: 'Fraunces', 'Playfair Display', Georgia, serif;
  font-optical-sizing: auto;
  font-variation-settings: "SOFT" 0, "WONK" 0;
  letter-spacing: -0.018em;
}

.eyebrow {
  font-family: 'Inter', sans-serif;
  font-size: 11.5px;
  font-weight: 600;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--ink);
}

.hairline {
  border-color: rgba(29, 26, 23, 0.18);
}

/* Stronger link/CTA/label defaults */
.arrow-link { display: inline-flex; align-items: center; gap: 8px; font-weight: 500; }
.arrow-link .arrow { transition: transform 0.3s ease; }
.arrow-link:hover .arrow { transform: translateX(4px); }

.text-ink-soft { color: var(--ink-2); }

@keyframes fadeUp {
  from { opacity: 0; transform: translateY(10px); }
  to { opacity: 1; transform: translateY(0); }
}
.reveal { animation: fadeUp 0.9s ease-out both; }

@keyframes testimonialFade {
  from { opacity: 0; transform: translateY(6px); }
  to   { opacity: 1; transform: translateY(0); }
}
.testimonial-fade { animation: testimonialFade 500ms ease-out both; }

@keyframes marqueeScroll {
  from { transform: translate3d(0, 0, 0); }
  to   { transform: translate3d(-50%, 0, 0); }
}
.marquee-track {
  animation: marqueeScroll 45s linear infinite;
  will-change: transform;
}
.marquee-mask {
  -webkit-mask-image: linear-gradient(to right, transparent 0, #000 6%, #000 94%, transparent 100%);
          mask-image: linear-gradient(to right, transparent 0, #000 6%, #000 94%, transparent 100%);
}

.hero-img { transform: scale(1.01); transition: transform 1.2s ease-out; }
.hero-img.in { transform: scale(1); }

.hp-field {
  position: absolute;
  left: -9999px;
  width: 1px;
  height: 1px;
  opacity: 0;
  pointer-events: none;
}

/* Anti-spam field for the quick consultation drawer */
.fl-hp {
  position: absolute;
  left: -9999px;
  top: auto;
  width: 1px;
  height: 1px;
  overflow: hidden;
  opacity: 0;
  pointer-events: none;
}

/* ── Page enter transition (route change) ────────────────── */
@keyframes pageEnter {
  from { opacity: 0; }
  to   { opacity: 1; }
}
.page-enter {
  animation: pageEnter 380ms cubic-bezier(0.22, 1, 0.36, 1) both;
  will-change: opacity;
}
/* NOTE: do NOT animate transform here. A transform on this wrapper would
   become the containing block for position:fixed descendants (SiteNav),
   breaking the sticky top nav. Opacity-only is safe. */

/* ── Form field focus polish ─────────────────────────────── */
input, textarea, select {
  transition: border-color 220ms ease-out, color 220ms ease-out;
}

/* ── Mobile nav panel enter ────────────────────────── */
@keyframes mobileMenuEnter {
  from { opacity: 0; transform: translate3d(0, -6px, 0); }
  to   { opacity: 1; transform: translate3d(0, 0, 0); }
}
.mobile-menu-enter {
  animation: mobileMenuEnter 240ms cubic-bezier(0.22, 1, 0.36, 1) both;
}

/* ── Reduced motion — respect user preference ────────────── */
@media (prefers-reduced-motion: reduce) {
  .page-enter,
  .reveal,
  .testimonial-fade,
  .marquee-track,
  .mobile-menu-enter,
  .hero-img {
    animation: none !important;
    transition: none !important;
    transform: none !important;
    opacity: 1 !important;
  }
}

@keyframes bokehFloat {
  0%, 100% { transform: translate3d(0, 0, 0) scale(1); }
  50%      { transform: translate3d(0, -22px, 0) scale(1.08); }
}
.bokeh {
  animation: bokehFloat 14s ease-in-out infinite;
}

@keyframes drawerIn {
  from { transform: translate3d(100%, 0, 0); }
  to   { transform: translate3d(0, 0, 0); }
}
.drawer-in {
  animation: drawerIn 420ms cubic-bezier(0.16, 1, 0.3, 1) both;
}

@media (prefers-reduced-motion: reduce) {
  .bokeh, .drawer-in { animation: none !important; }
